exercises.solution:
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

func getItem(id int) (string, error) {
    if id < 0 {
        return "", ErrNotFound
    }
    return "item", nil
}

func main() {
    _, err := getItem(-1)
    if errors.Is(err, ErrNotFound) {
        fmt.Println("not found")
    }
}
